use rune::{col, el, text, El};
use crate::{open_file, State};
use super::theme::*;
fn row(label:&'static str, shortcut:&'static str, f:impl Fn(&mut State)+'static)->El { el().h(32.0).w_full().padding(0.0).radius(6.0).hover(HOVER).center().child(text(label).color(TEXT)).child(el().grow(1.0)).child(text(shortcut).color(SECONDARY)).on_press(f) }
pub fn view(_s:&State)->El { col().key("menu-popover").w(220.0).padding(6.0).gap(2.0).radius(12.0).fill(POPOVER).border(1.0,BORDER).pin(None,Some(48.0),Some(8.0),None).child(row("New Window","Ctrl+N",|s|s.show_menu=false)).child(row("Open...","Ctrl+O",|s|{open_file(s);s.show_menu=false;})).child(el().h(1.0).fill(BORDER)).child(row("Open With...","Shift+Ctrl+O",|s|s.show_menu=false)).child(row("Print...","Ctrl+P",|s|s.show_menu=false)).child(el().h(1.0).fill(BORDER)).child(row("Rotate","↶   ↷",|s|s.show_menu=false)).child(el().h(1.0).fill(BORDER)).child(row("Set as Background...","Ctrl+F8",|s|s.show_menu=false)).child(row("Delete","Delete",|s|s.show_menu=false)).child(el().h(1.0).fill(BORDER)).child(row("Help","F1",|s|s.show_menu=false)).child(row("Keyboard Shortcuts","Ctrl+?",|s|s.show_menu=false)).child(row("About Veyra","",|s|s.show_menu=false)) }
